const DECIMAL = /^[+-]?[0-9]+(?:\.[0-9]+)?$/;

function parse(text) {
  let sign = 1n;
  let rest = text;
  if (rest[0] === '+') rest = rest.slice(1);
  else if (rest[0] === '-') {
    sign = -1n;
    rest = rest.slice(1);
  }
  const dot = rest.indexOf('.');
  const whole = dot === -1 ? rest : rest.slice(0, dot);
  const fraction = dot === -1 ? '' : rest.slice(dot + 1);
  return { value: sign * BigInt(whole + fraction), scale: fraction.length };
}

export function addDecimal(a, b) {
  if (typeof a !== 'string' || typeof b !== 'string') {
    throw new TypeError('both arguments must be strings');
  }
  if (!DECIMAL.test(a) || !DECIMAL.test(b)) {
    throw new SyntaxError('a decimal number is optional sign, digits, then an optional fraction');
  }

  const left = parse(a);
  const right = parse(b);
  const scale = Math.max(left.scale, right.scale);
  const lift = (part) => part.value * 10n ** BigInt(scale - part.scale);

  let total = lift(left) + lift(right);
  const negative = total < 0n;
  if (negative) total = -total;

  const digits = total.toString().padStart(scale + 1, '0');
  const cut = digits.length - scale;
  let whole = digits.slice(0, cut).replace(/^0+(?=[0-9])/, '');
  const fraction = digits.slice(cut).replace(/0+$/, '');
  if (whole === '') whole = '0';

  const body = fraction === '' ? whole : `${whole}.${fraction}`;
  return negative ? `-${body}` : body;
}
